#include <string.h>

void reverse(int a[], int n) {
    int i = 0;
    int j = n - 1;
    int temp;
    while (i <= j) {
        temp = a[i];
        a[i] = a[j];
        a[j] = temp;
        i = i + 1;
        j = j - 1;
